000250 |     private static WorkbookLayout buildLayout(ExportSpec spec,
000251 |             PensionBatchExportRequest request, DateRange range, int columnCount) {
000252 |         List<Object[]> leadingRows = new ArrayList<Object[]>();
000253 |         for (int i = 0; i < 7; i++) {
000254 |             leadingRows.add(new Object[columnCount]);
000255 |         }
000256 |         List<String> mergedRanges = new ArrayList<String>();
000257 |         String period = request.getRunMode() == PensionBatchRunMode.DAILY
000258 |                 ? wareki(range.from) : wareki(range.from) + "～" + wareki(range.to);
000259 |         String staff = request.getStaffNo() == null || request.getStaffNo().trim().length() == 0
000260 |                 ? "ALL" : request.getStaffNo().trim();
000261 | 
000262 |         Object[] titleRow = leadingRows.get(0);
000263 |         Object[] metaRow = leadingRows.get(4);
000264 |         if (spec.type == AuditType.NEW) {
000265 |             titleRow[3] = spec.title;
000266 |             metaRow[3] = "処理日";
000267 |             metaRow[5] = period;
000268 |             metaRow[9] = "職員番号";
000269 |             metaRow[11] = staff;
000270 |             mergedRanges.add("D1:M3");
000271 |             mergedRanges.add("D5:E6");
000272 |             mergedRanges.add(request.getRunMode() == PensionBatchRunMode.DAILY
000273 |                     ? "F5:H6" : "F5:I6");
000274 |             mergedRanges.add("J5:K6");
000275 |             mergedRanges.add("L5:M6");
000276 |         } else {
000277 |             titleRow[4] = spec.title;
000278 |             metaRow[4] = "処理日";
000279 |             metaRow[6] = period;
000280 |             metaRow[11] = "職員番号";
000281 |             metaRow[13] = staff;
000282 |             mergedRanges.add("E1:P3");
000283 |             mergedRanges.add("E5:F6");
000284 |             mergedRanges.add(request.getRunMode() == PensionBatchRunMode.DAILY
000285 |                     ? "G5:H6" : "G5:I6");
000286 |             mergedRanges.add("L5:M6");
