000302 |             List<GeneratedFile> generated) {
000303 |         List<PensionBatchExportFileResult> results =
000304 |                 new ArrayList<PensionBatchExportFileResult>();
000305 |         for (int i = 0; i < generated.size(); i++) {
000306 |             GeneratedFile file = generated.get(i);
000307 |             results.add(new PensionBatchExportFileResult(file.spec.queryName,
000308 |                     file.spec.fileName, file.spec.type.getDisplayName(), file.rowCount));
000309 |         }
