000104 | 							int method) throws Exception{
000105 | 		FWSessionAgent agent = null;	// エージェント
000106 | 		HttpSession session = null;	// セッション
000107 | 
000108 | 		// 処理を開始します
000109 | 		while (agent == null) {
000110 | 			// セッション（HttpSession）を獲得します。
000111 | 			session = request.getSession(true);
000112 | 			if (session == null) {
000113 | 				// セッションオブジェクトは得られない場合、致命的なエラー。
000114 | 				this.returnHttpErrorResponse(response, null, "INTERNAL ERROR (session tracking error).", STATUS_ERROR);
000115 | 				return;
000116 | 			}
000117 | 
000118 | 			//--------------------------------------------------------------
000119 | 			// エージェントを獲得します。
000120 | 			// セッション単位でエージェントオブジェクトを１個ずつ持ちます。
000121 | 			//--------------------------------------------------------------
000122 | 			try {
000123 | 				// キー AGENTNAME で FWSessionAgent オブジェクトを保持しています。
000124 | 				agent = (FWSessionAgent)session.getAttribute(AGENTNAME);
000125 | 				if (agent == null) {		// 新規セッションの場合
000126 | 					synchronized (_sessionLock) {
000127 | 						// 新規に FWSessionAgent インスタンスを生成します。
000128 | 						FWLog.debug(this.getClass(), "agent new: SID=" + session.getId());
000129 | 						agent = new FWSessionAgent(session.getId(), null, null);
000130 | 					}
000131 | 
000132 | 					if (_timeout > 0) {
000133 | 						// セッションタイマーをセットします。
000134 | 						agent.setSessionTimer(_timeout, this, session);
000135 | 					}
000136 | 
000137 | 					// このセッションで作成したエージェントを保持します。
000138 | 					
000139 | 					session.setAttribute(AGENTNAME, agent);
000140 | 				} else {			// 継続セッションの場合
000141 | 					agent.stopTimer();	// タイマーを止めます。
000142 | 				}
000143 | 			} catch (FMSystemException e) {
000144 | 				throw e;
000145 | 			} catch (FMPropertyException e) {
000146 | 				int code = e.getStatusCode();
000147 | 				this.returnHttpErrorResponse(response, null, e.getMessage(), code);
000148 | 				if (session != null) {
000149 | 					session.invalidate();
000150 | 				}
000151 | 				return;
000152 | 			} catch (IllegalStateException e) {
000153 | 				if (session != null) {
000154 | 					session.invalidate();
000155 | 				}
000156 | 				agent = null;
000157 | 				continue;
000158 | 			}
000159 | 
000160 | 			synchronized (agent) {
000161 | 				// エージェントを獲得・ロックしたので、セッションの正当性を再確認します。
000162 | 				if (agent != (FWSessionAgent)session.getAttribute(AGENTNAME)) {
000163 | 					throw new IllegalStateException();
