000015 |     private static final Pattern ERA_DATE = Pattern.compile(
000016 |             "^(\u4ee4\u548c|\u5e73\u6210|\u662d\u548c|\u5927\u6b63|\u660e\u6cbb|R|H|S|T|M)\\s*"
000017 |             + "(\u5143|[0-9]{1,3})[\\./\\-\u5e74]\\s*([0-9]{1,2})[\\./\\-\u6708]\\s*"
000018 |             + "([0-9]{1,2})\u65e5?$", Pattern.CASE_INSENSITIVE);
000019 |     private static final Pattern GREGORIAN_DATE = Pattern.compile(
000020 |             "^([0-9]{4})[\\./\\-]([0-9]{1,2})[\\./\\-]([0-9]{1,2})$");
000021 |     private static final Pattern COMPACT_DATE = Pattern.compile("^([0-9]{4})([0-9]{2})([0-9]{2})$");
000022 | 
000023 |     private static final Era[] ERAS = {
000024 |         new Era("M", "明治", 1868, "1868-09-08", "1912-07-29"),
000025 |         new Era("T", "大正", 1912, "1912-07-30", "1926-12-24"),
000026 |         new Era("S", "昭和", 1926, "1926-12-25", "1989-01-07"),
000027 |         new Era("H", "平成", 1989, "1989-01-08", "2019-04-30"),
000028 |         new Era("R", "令和", 2019, "2019-05-01", null)
000029 |     };
