000071 |         throw invalid(value);
000072 |     }
000073 | 
000074 |     public static String toGregorianDisplay(String value) {
000075 |         String iso = toIsoDate(value);
000076 |         return iso.length() == 0 ? "" : iso.replace('-', '/');
000077 |     }
000078 | 
000079 |     /** R 08/06/11 形式の表示値を返す。 */
000080 |     public static String toWarekiDisplay(String value) {
000081 |         String iso = toIsoDate(value);
000082 |         if (iso.length() == 0) {
000083 |             return "";
000084 |         }
000085 |         Date date = parseIso(iso, value);
000086 |         Era era = eraFor(date);
000087 |         Calendar calendar = new GregorianCalendar();
000088 |         calendar.setTime(date);
000089 |         int eraYear = calendar.get(Calendar.YEAR) - era.baseYear + 1;
000090 |         return era.code + " " + twoOrMoreDigits(eraYear) + "/"
000091 |                 + twoDigits(calendar.get(Calendar.MONTH) + 1) + "/"
000092 |                 + twoDigits(calendar.get(Calendar.DAY_OF_MONTH));
000093 |     }
000094 | 
000095 |     /** Access Format(..., "ge.mm.dd") に近い R8.06.11 形式。 */
000096 |     public static String toAccessWareki(String value) {
000097 |         String display = toWarekiDisplay(value);
000098 |         if (display.length() == 0) {
000099 |             return "";
000100 |         }
000101 |         String[] fields = display.substring(2).split("/");
000102 |         int year = Integer.parseInt(fields[0]);
000103 |         return display.substring(0, 1) + year + "." + fields[1] + "." + fields[2];
000104 |     }
