000139 |     private static String normalizeInput(String value) {
000140 |         if (value == null) {
000141 |             return "";
000142 |         }
000143 |         String result = Normalizer.normalize(value, Normalizer.Form.NFKC).trim();
000144 |         result = result.replace('　', ' ');
000145 |         return result;
000146 |     }
